var rawTrim = (raw || '').replace(/^\s+|\s+$/g, '');
var meta = JSON.parse(rawTrim);
var b64 = String(meta.payload || '').replace(/[\s=]+$/g, '').replace(/\s+/g, '');
var chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
var output = '';
var buffer = 0;
var bits = 0;
for (var i = 0; i < b64.length; i++) {
  var v = chars.indexOf(b64.charAt(i));
  if (v < 0) continue;
  buffer = (buffer << 6) | v;
  bits += 6;
  if (bits >= 8) {
    bits -= 8;
    output += String.fromCharCode((buffer >> bits) & 0xff);
  }
}
var arr = JSON.parse(output);
return arr;
